// Helper: kisi city ka intel return karo agar usme kuch real bhara ho.
export function getCityLocalIntel(citySlug) {
  const x = cityLocalIntel[citySlug];
  if (!x) return null;
  const hasContent =
    (x.localContext && x.localContext.trim()) ||
    (x.areaNotes && x.areaNotes.length) ||
    (x.tips && x.tips.length) ||
    (x.faqs && x.faqs.length);
  return hasContent ? x : null;
}
